-- Inbound tables to be partitioned by month, for the PostgreSQL copy of the InvoiceSystem sample. Settings:
-- InboundTables=PartitionedWebhook,PartitionedErrorReport:Payload, PartitionTables=PartitionedWebhook,PartitionedErrorReport
-- No unique index on the event id (see partition_mssql.sql). Rows in five months, so the script has old partitions to make.
CREATE TABLE IF NOT EXISTS "PartitionedWebhook" (
    "PartitionedWebhookId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Source" varchar(40) NULL,
    "EventId" varchar(80) NULL,
    "Body" varchar(4000) NOT NULL,
    "ReceivedOn" timestamp NOT NULL DEFAULT now(),
    "ProcessedOn" timestamp NULL
);
CREATE INDEX IF NOT EXISTS "IX_PartitionedWebhook_Source" ON "PartitionedWebhook" ("Source");
INSERT INTO "PartitionedWebhook" ("Source", "EventId", "Body", "ReceivedOn", "ProcessedOn")
SELECT * FROM (VALUES
    ('seed', 'seed-1', '{"seed":1}', '2026-07-03 10:00'::timestamp, '2026-07-03 10:05'::timestamp),
    ('seed', 'seed-2', '{"seed":2}', '2026-07-28 23:59'::timestamp, NULL::timestamp),
    ('seed', 'seed-3', '{"seed":3}', '2026-08-15 12:00'::timestamp, NULL::timestamp),
    ('seed', 'seed-4', '{"seed":4}', '2026-09-01 00:00'::timestamp, NULL::timestamp),
    ('seed', 'seed-5', '{"seed":5}', '2026-10-20 08:30'::timestamp, NULL::timestamp),
    ('seed', 'seed-6', '{"seed":6}', '2026-11-02 09:15'::timestamp, NULL::timestamp)
) AS v WHERE NOT EXISTS (SELECT 1 FROM "PartitionedWebhook");

CREATE TABLE IF NOT EXISTS "PartitionedErrorReport" (
    "PartitionedErrorReportId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" varchar(100) NULL,
    "Severity" varchar(20) NULL,
    "Payload" text NOT NULL,
    "ReceivedAt" timestamp NOT NULL DEFAULT now(),
    "IsProcessed" boolean NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS "IX_PartitionedErrorReport_Severity" ON "PartitionedErrorReport" ("Severity");
INSERT INTO "PartitionedErrorReport" ("Title", "Severity", "Payload", "ReceivedAt", "IsProcessed")
SELECT * FROM (VALUES
    ('seed', 'error', '{"seed":1}', '2026-08-04 10:00'::timestamp, true),
    ('seed', 'warning', '{"seed":2}', '2026-09-30 23:59'::timestamp, false),
    ('seed', 'error', '{"seed":3}', '2026-10-01 00:00'::timestamp, false),
    ('seed', 'info', '{"seed":4}', '2026-11-03 17:45'::timestamp, false)
) AS v WHERE NOT EXISTS (SELECT 1 FROM "PartitionedErrorReport");
